        note = Note(text=text)
        db.session.add(note)
        db.session.commit()
        return jsonify(id=note.id, text=note.text), 201

    @app.get("/notes")
    def list_notes():
        notes = db.session.execute(db.select(Note).order_by(Note.id)).scalars()
        return jsonify([{"id": n.id, "text": n.text} for n in notes])

